CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE, phone TEXT, password_hash TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, parent_id INTEGER REFERENCES categories(id));
CREATE TABLE brands (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL);
CREATE TABLE products (id INTEGER PRIMARY KEY, category_id INTEGER, brand_id INTEGER, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, price DECIMAL(12,2) NOT NULL, stock INTEGER DEFAULT 0, description TEXT, status TEXT DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_images (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL, image_url TEXT NOT NULL, sort_order INTEGER DEFAULT 0);
CREATE TABLE carts (id INTEGER PRIMARY KEY, user_id INTEGER, session_id TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items (id INTEGER PRIMARY KEY, cart_id INTEGER NOT NULL, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL DEFAULT 1);
CREATE TABLE orders (id INTEGER PRIMARY KEY, user_id INTEGER, customer_name TEXT, phone TEXT, address TEXT, subtotal DECIMAL(12,2), delivery_fee DECIMAL(12,2), total DECIMAL(12,2), status TEXT DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL, product_id INTEGER, product_name TEXT, price DECIMAL(12,2), quantity INTEGER);
CREATE TABLE wishlists (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, product_id INTEGER NOT NULL);
CREATE TABLE sliders (id INTEGER PRIMARY KEY, title TEXT, image_url TEXT, link_url TEXT, status TEXT DEFAULT 'active', sort_order INTEGER DEFAULT 0);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
